    outline: none;
    background-color: var(--wg-paper);
    background-image: repeating-linear-gradient(to bottom,
        transparent 0 calc(var(--wg-edit-lh) - 1px),
        var(--wg-print-faint) calc(var(--wg-edit-lh) - 1px) var(--wg-edit-lh));
    background-position: 0 12px;
    background-attachment: local;
    line-height: var(--wg-edit-lh);
    transition: border-color var(--animation-duration-2x) ease;
}

