/* ======================================================================
   Wongoji 1.0.51 — 알림(토스트): 청회색 이중 테두리의 작은 원고 쪽지,
   왼쪽에 종류별 한자 도장(完 告 注 誤)
   ====================================================================== */
body #toast-container > div.toast {
    --wg-toast-tone: var(--wg-print);
    width: min(300px, calc(100vw - 32px));
    box-sizing: border-box;
    margin-bottom: 8px;
    padding: 11px 30px 11px 56px;
    background: #141414 none !important;
    color: var(--wg-ink-body);
    border: 1px solid var(--wg-toast-tone) !important;
    border-radius: 2px;
    box-shadow: inset 0 0 0 3px #141414, inset 0 0 0 4px var(--wg-print-faint) !important;
    opacity: 1;
    font-family: var(--wg-serif);
    font-size: calc(var(--mainFontSize) * 1.05);
    line-height: 1.6;
    text-shadow: none;
}
/* 종류별 도장 */
body #toast-container > div.toast::before {
    content: '告';
    position: absolute;
    left: 13px;
    top: 50%;
    width: 28px;
    height: 28px;
    margin-top: -14px;
    box-sizing: border-box;
    display: grid;
    place-items: center;
    border: 1px solid var(--wg-toast-tone);
    box-shadow: 0 0 0 2px #141414, 0 0 0 3px var(--wg-toast-tone);
    background: #141414;
    font-family: var(--wg-hanja);
    font-size: 15px;
    font-weight: 600;
    line-height: 1;
    color: var(--wg-toast-tone);
    transform: rotate(-6deg);
}
body #toast-container > div.toast-success::before { content: '完'; }
body #toast-container > div.toast-info::before    { content: '告'; }
body #toast-container > div.toast-warning::before { content: '注'; }
body #toast-container > div.toast-error::before   { content: '誤'; }
body #toast-container > div.toast-success { --wg-toast-tone: var(--wg-print); }
body #toast-container > div.toast-info    { --wg-toast-tone: var(--wg-print); }
body #toast-container > div.toast-warning { --wg-toast-tone: var(--wg-ink-soft); }
body #toast-container > div.toast-error   { --wg-toast-tone: var(--wg-ink); }

body #toast-container > div.toast .toast-title {
    margin-bottom: 3px;
    padding-bottom: 3px;
    border-bottom: 1px dotted var(--wg-print-line);
    font-family: var(--wg-title);
    font-weight: 700;
    letter-spacing: .02em;
    color: var(--wg-ink);
}
body #toast-container > div.toast .toast-message {
    color: var(--wg-ink-soft);
    word-break: keep-all;
    overflow-wrap: anywhere;
}
body #toast-container > div.toast .toast-message a {
    color: var(--wg-quote);
}
body #toast-container > div.toast .toast-close-button {
    position: absolute;
    top: 6px;
    right: 9px;
    padding: 0;
    color: var(--wg-ink-faint);
    text-shadow: none;
    opacity: 1;
    font-weight: 400;
}
body #toast-container > div.toast .toast-progress {
    left: 4px;
    bottom: 4px;
    height: 2px;
    max-width: calc(100% - 8px);
    background-color: var(--wg-toast-tone);
    opacity: .5;
}
body #toast-container.toast-top-center > div.toast,
body #toast-container.toast-bottom-center > div.toast {
    margin-left: auto;
    margin-right: auto;
}

/* ======================================================================
   Wongoji 1.0.52 — 이름 속 이모지도 한 칸에 맞춥니다.
   컬러 이모지 글꼴은 글자 폭이 1.25em 이라 한글(0.96em)보다 넓어 뒤 글자를
   밀어냅니다. 기기의 이모지 글꼴을 이름 칸에서만 한글 폭으로 줄여 씁니다.
   ====================================================================== */
@font-face {
    font-family: 'WG Cell Emoji';
    src: local('Noto Color Emoji'), local('NotoColorEmoji'),
         local('Apple Color Emoji'), local('AppleColorEmoji'),
         local('Segoe UI Emoji'), local('SegoeUIEmoji');
    unicode-range: U+00A9, U+00AE, U+203C, U+2049, U+2122, U+2139, U+2194-21AA,
        U+231A-23FF, U+24C2, U+25AA-25FE, U+2600-27BF, U+2934-2935, U+2B05-2B55,
        U+3030, U+303D, U+3297, U+3299, U+FE0F, U+200D, U+20E3, U+1F000-1FAFF, U+E0020-E007F;
    size-adjust: 76.8%;
    ascent-override: 88%;
    descent-override: 22%;
    line-gap-override: 0%;
    font-display: swap;
}

/* Dark edition — 본문 글씨 밝기 */
:root {
    --wg-ink-body: #c6c8cd;
    --wg-em: #8c9095;
    --wg-quote: #86a3c0;
}
